use xiom.io;

use xiom.string;
fn main() {
  let message = "I Love Ice Cream";

  io.println("Original message:");
  io.println(message);

  let shouted = string.str_upper(message);
  io.println("Shouted:");
  io.println(shouted);

  let whispered = string.str_lower(message);
  io.println("Whispered:");
  io.println(whispered);

  let name = "alex";
  let loud_name = string.str_upper(name);
  io.println("Friend's name in caps:");
  io.println(loud_name);
}
